const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the Western Pacific Ocean tropical region
  // Approx: 120°E to 180°E, 20°S to 20°N
  const westernPacific = ee.Geometry.Rectangle([120, -20, 180, 20]);

  const year1998_start = '1998-01-01';
  const year1998_end = '1998-12-31';
  const year2009_start = '2009-01-01';
  const year2009_end = '2009-12-31';

  const bandName = 'precipitation'; // Band for rainfall rate

  // 2. Data Acquisition & Check
  const trmm1998 = ee.ImageCollection('TRMM/3B43V7')
    .filterDate(year1998_start, year1998_end)
    .filterBounds(westernPacific);

  const trmm2009 = ee.ImageCollection('TRMM/3B43V7')
    .filterDate(year2009_start, year2009_end)
    .filterBounds(westernPacific);

  const size1998 = await trmm1998.size().getInfo();
  const size2009 = await trmm2009.size().getInfo();

  console.log(`1998 Collection Size: ${size1998}`);
  console.log(`2009 Collection Size: ${size2009}`);

  if (size1998 === 0 || size2009 === 0) {
    console.log("C1: Empty Collection (No images found for one or both years).");
    return;
  }

  // Calculate annual mean rainfall
  const mean1998 = trmm1998.select(bandName).mean();
  const mean2009 = trmm2009.select(bandName).mean();

  // 3. Processing & 4. Calculation
  // TRMM data resolution is 0.25 degrees (~27.8 km at equator)
  // Use a scale of 30000 meters to avoid memory issues and be consistent with data resolution.
  const scale = 30000; // meters

  const stats1998 = await mean1998.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westernPacific,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  const stats2009 = await mean2009.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westernPacific,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  // Check for C2/C3 - No Valid Pixels / Calculation Failure
  if (stats1998 === null || isNaN(stats1998) || stats2009 === null || isNaN(stats2009)) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid after reduction).");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Mean tropical rainfall (1998): ${stats1998.toFixed(4)} mm/hour`);
  console.log(`Mean tropical rainfall (2009): ${stats2009.toFixed(4)} mm/hour`);

  if (stats2009 > stats1998) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
